SELECT 



        (t.ticket_no LIKE CONCAT('%', #{keyword}, '%') OR t.title LIKE CONCAT('%', #{keyword}, '%')
         OR c.name LIKE CONCAT('%', #{keyword}, '%') OR t.serial_no = #{keyword})

    AND t.type = #{type}
    AND t.priority = #{priority}
    AND t.status = #{status}
    AND t.customer_id = #{customerId}
    AND t.assignee_id = #{assigneeId}
    AND t.status IN ('OPEN', 'PROCESSING') AND t.due_time < NOW()

ORDER BY CASE WHEN t.status IN ('OPEN', 'PROCESSING') THEN 0 ELSE 1 END, t.due_time, t.id DESC
